\begin{ex}%[8D1V4]
Thu gọn đa thức $- 6 x^{2}-\left(- 7 x - 1\right) \left(x - 7\right)$
\choice
{ ${x^{2} + 50 x - 7}$ }
   { ${x^{2} - 48 x + 7}$ }
     { ${- 13 x^{2} - 48 x - 7}$ }
    { \True ${x^{2} - 48 x - 7}$ }
\loigiai{
$- 6 x^{2}-\left(- 7 x - 1\right) \left(x - 7\right)=x^{2} - 48 x - 7$
}\end{ex}

\begin{ex}%[8D1V4]
Thu gọn đa thức $6 x^{2}-\left(x - 2\right) \left(5 x + 8\right)$
\choice
{ ${x^{2} + 18 x + 16}$ }
   { \True ${x^{2} + 2 x + 16}$ }
     { ${11 x^{2} + 2 x + 16}$ }
    { ${x^{2} + 2 x - 16}$ }
\loigiai{
Phân tích tử và mẫu thành nhân tử (hoặc khai triển hằng đẳng thức, quy đồng/nghịch đảo phép chia) rồi rút gọn: $6 x^{2}-\left(x - 2\right) \left(5 x + 8\right) = x^{2} + 2 x + 16$.
}\end{ex}

